async function showPlatformSetup(){
 homeMain.hidden=true;detailMain.hidden=false;document.title='Platform setup — BlueMint';
 if(chartObserver){chartObserver.disconnect();chartObserver=null}
 detailMain.innerHTML='<div class="empty">Checking platform setup on devnet…</div>';
 try{
  const data=await api('/platform');if(location.hash!=='#setup')return;
  const owner=apiState.session?.wallet===data.owner;
  const sol=x=>(Number(x)/1e9).toFixed(8).replace(/0+$/,'').replace(/\.$/,'');
  detailMain.innerHTML=`<div class="token-breadcrumb"><a href="#create">Back to launch</a><span>/ Platform setup</span></div><span class="eyebrow blue">OWNER SETUP · SOLANA DEVNET</span><h1>Build the foundation.</h1><p class="modal-sub">Create BlueMint’s LaunchLab platform configuration. This is a test-network setup, not a token launch.</p><section class="chain-actions"><h3>${data.configured?'Platform verified':data.accountExists?'Existing platform needs review':'Ready for owner review'}</h3><div class="split"><span>Owner / LP Fee Key wallet</span><code>${esc(data.owner)}</code></div><div class="split"><span>Fee-collection wallet</span><code>${esc(data.feeWallet)}</code></div><div class="split"><span>Platform address</span><code>${esc(data.platformId)}</code></div><div class="split"><span>Wallet balance</span><b>${sol(data.balanceLamports)} devnet SOL</b></div><div class="split"><span>Bonding-curve platform fee</span><b>1.25% + Raydium protocol fee</b></div><div class="split"><span>Extra curve creator fee</span><b>0%</b></div><div class="split"><span>Selected CPMM rates after graduation</span><b>1.25% creator + 0.25% trading</b></div><p>CPMM creator fees are assigned to your fee-collection wallet. These are configuration settings; no pool or trading activity exists yet.</p><div class="split"><span>Graduated LP policy</span><b>100% locked · 0% burned</b></div><p>The platform owner receives the LP Fee Key and its fee-claim rights. No creator or holder rewards. The 40% treasury / 60% liquidity split and automated reinvestment are not implemented by this transaction.</p><div class="info-box"><b>Circle USDC only</b><p>${data.circleUsdcSupported?'A compatible Circle USDC quote configuration was found. Token launches still require separate verification and enablement.':'No compatible Circle USDC LaunchLab global config was found on devnet. This platform can be created, but token launches remain blocked. No substitute test token will be used.'}</p></div>${!owner?'<p>Connect the configured owner wallet on the <a href="#create">launch page</a>, then return here.</p>':''}${data.configurationIssue?`<p>${esc(data.configurationIssue)}</p>`:''}<button class="pixel-mint-button" id="preparePlatform" ${!owner||data.accountExists?'disabled':''}>Prepare setup transaction</button><button class="text-btn" id="verifyPlatform" ${!owner?'disabled':''}>Verify setup</button><p id="setupResult" role="status"></p></section>`;
  $('#verifyPlatform').onclick=async()=>{try{$('#setupResult').textContent='Checking finalized platform accounts…';await api('/platform/confirm',{method:'POST',body:'{}'});await showPlatformSetup();toast('Devnet platform verified.')}catch(e){$('#setupResult').textContent=e.message}};
  $('#preparePlatform').onclick=async()=>{
   const result=$('#setupResult'),button=$('#preparePlatform');button.disabled=true;result.textContent='Building and simulating your setup…';
   try{
    const p=await api('/platform/prepare',{method:'POST',body:'{}'});const summary=p.summary;
    open(`<span class="eyebrow blue">DEVNET SETUP REVIEW</span><h2>Create BlueMint platform</h2><div class="split"><span>Curve platform fee</span><b>1.25%</b></div><div class="split"><span>CPMM creator / trading fee settings</span><b>1.25% / 0.25%</b></div><div class="split"><span>Graduated LP</span><b>100% locked to platform Fee Key</b></div><p class="modal-sub">Owner and Fee Key recipient: ${esc(summary.owner)}<br>Fee collector: ${esc(summary.feeWallet)}</p><div class="split"><span>Account rent</span><b>${sol(summary.rentLamports)} devnet SOL</b></div><div class="split"><span>Estimated network fee</span><b>${sol(summary.networkFeeLamports)} devnet SOL</b></div><div class="split"><span>Estimated total</span><b>${sol(summary.estimatedTotalLamports)} devnet SOL</b></div><div class="info-box">Simulation passed. Two instructions create the platform and set its CPMM fee recipient. This does not enable Circle USDC launches, enforce the 40/60 split, or move mainnet funds.</div><button class="pixel-mint-button full" id="signPlatform">Review and sign in wallet</button>`);
    $('#signPlatform').onclick=async()=>{const sign=$('#signPlatform');sign.disabled=true;try{const transaction=await BlueMintWallet.signPrepared(p.transaction,apiState.session.wallet);const sent=await api('/platform/submit',{method:'POST',body:JSON.stringify({id:p.id,transaction})});modal.close();result.textContent='Submitted on devnet: '+sent.signature+'. Wait for finalization, then select Verify setup.'}catch(e){sign.disabled=false;toast(e.message)}};
    result.textContent='Simulation passed. Review the setup in the dialog.';
   }catch(e){result.textContent=e.message}finally{button.disabled=false}
  };
 }catch(e){if(location.hash==='#setup')detailMain.innerHTML=`<div class="empty"><h2>Setup is temporarily unavailable.</h2><p>${esc(e.message)}</p><a href="#create">Back to launch</a></div>`}
}
if(location.hash==='#setup'&&apiState.enabled)showPlatformSetup();
